{
  "table": {
    "name": "users",
    "purpose": "One row per registered user account on a Stack Exchange-style Q&A site (the companion tables posts, comments, votes, badges, postHistory, postLinks, tags match the standard Stack Exchange data-dump schema). Each row holds the user's public profile fields (display name, about-me, location, website, avatar) plus denormalized per-user site statistics (reputation, votes cast, profile views) and account timestamps. Id -1 represents the system/'Community' user."
  },
  "columns": {
    "AboutMe": {
      "role": "free_text",
      "name": "AboutMe",
      "description": "Free-text 'About me' biography from the user's profile, stored as an HTML fragment (<p>...</p>); null for ~77% of users. Recurring placeholder texts ('please delete me', 'merge keep') are account-deletion/merge requests.",
      "status": "resolved"
    },
    "AccountId": {
      "role": "identifier",
      "name": "AccountId",
      "description": "Network-wide account identifier on the parent platform (the Stack Exchange global account id that links the same person across sites), distinct from the site-local Id primary key; unique per row and not joined to any table in this database. -1 denotes the system/Community user.",
      "status": "resolved"
    },
    "Age": {
      "role": "numeric",
      "name": "Age",
      "description": "Self-reported age of the user in whole years (range 13-94, median ~30); null for ~79% of users who never filled it in.",
      "status": "resolved"
    },
    "CreationDate": {
      "role": "date",
      "name": "CreationDate",
      "description": "Timestamp (stored as text) of when the user account was registered on the site; spans 2010-07-19 to 2014-09-14, i.e. the site's lifetime up to the dump date.",
      "status": "resolved"
    },
    "DisplayName": {
      "role": "category",
      "name": "DisplayName",
      "description": "Public display name shown on the user's profile and attached to their posts/comments; not unique (common first names repeat). Values like 'user34964' are auto-generated anonymous display names.",
      "status": "resolved"
    },
    "DownVotes": {
      "role": "numeric",
      "name": "DownVotes",
      "description": "Denormalized count of downvotes cast by the user on the site; 0 for ~98% of users, max 1,920.",
      "status": "resolved"
    },
    "Id": {
      "role": "identifier",
      "name": "Id",
      "description": "Primary key: site-local numeric user id. Referenced by badges.UserId, comments.UserId, postHistory.UserId, posts.OwnerUserId, posts.LastEditorUserId and votes.UserId. Id -1 is the system/'Community' user (used e.g. for community-owned posts and anonymous votes).",
      "status": "resolved"
    },
    "LastAccessDate": {
      "role": "date",
      "name": "LastAccessDate",
      "description": "Timestamp (stored as text) of the user's most recent site visit/login ('last seen'); never earlier than CreationDate and capped at the dump date 2014-09-14.",
      "status": "resolved"
    },
    "Location": {
      "role": "free_text",
      "name": "Location",
      "description": "Free-text, self-reported location from the profile (mostly 'City, Country' strings, occasionally a time zone such as 'UTC -6'); ~71% null.",
      "status": "resolved"
    },
    "ProfileImageUrl": {
      "role": "free_text",
      "name": "ProfileImageUrl",
      "description": "URL of the user's avatar/profile image, mostly gravatar.com hash URLs plus some Google/Facebook image URLs; the most frequent value (3,348 rows) is the default blank-gravatar identicon.",
      "status": "resolved"
    },
    "Reputation": {
      "role": "numeric",
      "name": "Reputation",
      "description": "The user's reputation score on the site (Stack Exchange reputation points earned from upvotes, accepted answers, bounties, etc.). Minimum 1; the very common value 101 = 1 starting point + 100 network 'association bonus'.",
      "status": "resolved"
    },
    "UpVotes": {
      "role": "numeric",
      "name": "UpVotes",
      "description": "Denormalized count of upvotes cast by the user on the site; 0 for ~78% of users, max 11,442.",
      "status": "resolved"
    },
    "Views": {
      "role": "numeric",
      "name": "Views",
      "description": "Number of times the user's profile page has been viewed; 0 for ~50% of users, max 20,932.",
      "status": "resolved"
    },
    "WebsiteUrl": {
      "role": "free_text",
      "name": "WebsiteUrl",
      "description": "Self-reported personal website URL from the profile; ~80% null, and the most common values are placeholder junk typed instead of a real URL ('http://none', 'http://None', 'http://N/A', 'http://-').",
      "status": "resolved"
    }
  }
}
